import type { FlatStyle } from '@inkoxide/style';
import { DEFAULT_SANS } from '@inkoxide/style/internal';

/**
 * The supported Tailwind subset, one entry per utility family. This table is the single source
 * for docs/TAILWIND_SUPPORT.md (generated by scripts/gen-tailwind-docs.ts, checked by
 * scripts/check-generated.sh) and for the mapper tests: every `examples` entry must map to
 * exactly that style.
 *
 * Lengths are points: 1rem = 12pt and 1px = 0.75pt, so `p-4` is 12pt.
 */
export interface SupportedFamily {
  group: 'Layout' | 'Flexbox' | 'Grid' | 'Spacing' | 'Sizing' | 'Position' | 'Visual' | 'Border' | 'Text';
  utilities: string;
  /** The engine `Style` field (or run property) it sets. */
  maps: string;
  notes?: string;
  examples: Record<string, FlatStyle>;
}

